% function pred_pm2d5_long = pm2d5_pred_model_long(train_data, test_data)

% MODEL: ridge regression on sliding windows
%        (7 days in -> next 24 hourly PM2.5 values out, one coefficient set per lead hour).
%  training targets = the training STATIC sensors AND all MOBILE sensors.
%     Each target's inputs come only from the OTHER devices (it never sees its own data).


% Load Data
close all
clear
clc

% REMOVE FOR ACTUAL FUNCTION, SHOULD TAKE FROM TRAIN_DATA
train_data = load('long_term_tianjin_train_val.mat');

% Split into mobile and static data
data_mobile = train_data.data_mobile(:);
data_static = train_data.data_static(:);

raw_mobile = data_mobile(:);  raw_static = data_static(:); % keep raw data values to compare after

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%% Data Cleaning %%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

vars       = {'hmd','tmp','spd','pm2d5','lat','lon'};
warmup_min = 5;    % minutes dropped at start of each mobile trip
minCount   = 10;   % min readings per minute
ma_win     = 5;    % moving-average window (min)

nMobile  = numel(data_mobile);
devices  = [data_mobile(:); data_static(:)];
isStatic = (1:numel(devices))' > nMobile;

%%\ 1. Clean each device and average to 1-minute values
for i = 1:numel(devices)
    T = table2timetable(devices{i}, 'RowTimes', 'time');
    T = T(:, vars);
    [~, iu] = unique(T.time);  T = T(iu, :);          % sort, remove duplicate times

    T.pm2d5(T.pm2d5 < 0   | T.pm2d5 > 1000) = NaN;    % impossible values -> NaN
    T.hmd(T.hmd     < 0   | T.hmd   > 100)  = NaN;
    T.tmp(T.tmp     < -30 | T.tmp   > 50)   = NaN;

    if ~isStatic(i)                                   % mobile: drop warm-up of each trip
        trip  = cumsum([1; diff(T.time) > minutes(10)]);
        start = T.time([true; diff(trip) > 0]);
        T = T(T.time >= start(trip) + minutes(warmup_min), :);
    end

    n = retime(T(:,'pm2d5'), 'minutely', @(x) sum(~isnan(x)));
    T = retime(T, 'minutely', @(x) mean(x, 'omitnan'));
    devices{i} = T(n.pm2d5 >= minCount, :);           % keep minutes with enough readings
end
data_mobile = devices(~isStatic);
data_static = devices(isStatic);

%%\ 2. Remove faulty static sensors (median PM2.5 is an outlier)
medPM     = cellfun(@(T) median(T.pm2d5, 'omitnan'), data_static);
removeIdx = find(isoutlier(medPM) | isnan(medPM))';
fprintf('Removing faulty static sensor(s): %s\n', mat2str(removeIdx)); %[output:29b59c54]
data_static(removeIdx) = [];

%%\ 3. Find co-located static sensors (same lat and lon)
loc = cell2mat(cellfun(@(T) median([T.lat T.lon], 1, 'omitnan'), data_static, 'UniformOutput', false));
[~, ~, grp] = unique(loc, 'rows');
colocGroups = {};
for gid = 1:max(grp) %[output:group:1f15c46b]
    if nnz(grp == gid) > 1
        colocGroups{end+1} = find(grp == gid)';       %#ok<SAGROW>
        fprintf('Co-located static sensors: %s\n', mat2str(colocGroups{end})); %[output:17405c8a]
    end
end %[output:group:1f15c46b]

%%\ 4. Merge each co-located group into one site (mean per minute)
mergedSites = cell(numel(colocGroups), 1);
for q = 1:numel(colocGroups)
    G = data_static(colocGroups{q});
    mergedSites{q} = rmmissing(retime(sortrows(vertcat(G{:})), 'minutely', @(x) mean(x, 'omitnan')), 'DataVariables', 'pm2d5');
end
data_static([colocGroups{:}]) = [];
mergedIdx   = numel(data_static) + (1:numel(mergedSites));
data_static = [data_static; mergedSites];

%%\ 5. Combine, smooth, convert to numeric
all_data = [data_mobile; data_static];
source   = [repmat("mobile", numel(data_mobile), 1); repmat("static", numel(data_static), 1)];
orig_idx = [(1:numel(data_mobile))'; (1:numel(data_static))'];

for i = 1:numel(all_data)
    T = all_data{i};
    pm_ma = movmean(T.pm2d5, minutes(ma_win), 'SamplePoints', T.time);
    % 1 time | 2 hmd | 3 tmp | 4 spd | 5 pm2d5 | 6 lat | 7 lon | 8 pm2d5 smoothed
    all_data{i} = [datenum(T.time) T.hmd T.tmp T.spd T.pm2d5 T.lat T.lon pm_ma];
end
timeUnit = 'datenum (days)';

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%% Train / validation split %%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Two splits at once:
%   SPACE: ONE static site is held out (validation dataset). It is never a training target and never an input,
%          so scoring it tests a location the model has not seen.
%   TIME : the sliding windows are split by date (further down). Training targets come from
%          the early part of the month, validation targets from the last valDays, with a
%          gapDays purge in between so overlapping windows cannot leak into each other.


% Cut the data into "windows". A window is a moment in time, the forecast start. Each window has:
% What the model sees: the 7 days before that moment, from the other sensors.
% What it must predict: the target sensor's average PM2.5 for each of the next 24 hours.
% A new window starts every 30 minutes.

candidates = find(source == "static");
fprintf('Static validation candidates: %s\n', mat2str(orig_idx(candidates)')); %[output:0aceff67]

valSeed = 42;                                         % fixed seed = same pick every run; [] = new random pick each run
if isempty(valSeed), rng('shuffle'); else, rng(valSeed); end
valIdx = candidates(randi(numel(candidates)));        % position of that sensor in all_data

valName = sprintf('static #%d', orig_idx(valIdx));
if ismember(orig_idx(valIdx), mergedIdx), valName = [valName ' (merged)']; end
fprintf('Validation sensor: %s at lat %.4f, lon %.4f\n', valName, ... %[output:group:30d22fde] %[output:1444997d]
    median(all_data{valIdx}(:,6), 'omitnan'), median(all_data{valIdx}(:,7), 'omitnan')); %[output:group:30d22fde] %[output:1444997d]
trainIdx = setdiff(1:numel(all_data), valIdx);
fprintf('Training devices: %d mobile, %d static\n', ... %[output:group:9d0d7e0e] %[output:52a64cd8]
    nnz(source(trainIdx) == "mobile"), nnz(source(trainIdx) == "static")); %[output:group:9d0d7e0e] %[output:52a64cd8]
for i = 1:numel(all_data) %[output:group:5c92752e]
    fprintf('%s #%d: median PM2.5 = %.1f\n', source(i), orig_idx(i), median(all_data{i}(:,5), 'omitnan')); %[output:8fd6ccd7]
end %[output:group:5c92752e]

%%\ Plot raw vs cleaned PM2.5
% match each cleaned device to the raw sensor(s) it came from
keptS  = setdiff(1:numel(raw_static), removeIdx);
soloS  = keptS(setdiff(1:numel(keptS), [colocGroups{:}]));
rawSrc = [cellfun(@(T) {T}, raw_mobile,        'UniformOutput', false);
    cellfun(@(T) {T}, raw_static(soloS), 'UniformOutput', false);
    cellfun(@(g) raw_static(keptS(g)), colocGroups(:), 'UniformOutput', false)];

gapBreak = minutes(30);     % don't draw a line across gaps longer than this

figure('Color', 'w', 'WindowState', 'maximized'); %[output:3d3acd46]
tiledlayout('flow', 'TileSpacing', 'tight', 'Padding', 'compact'); %[output:3d3acd46]
for i = 1:numel(all_data)
    nexttile; hold on; %[output:3d3acd46]
    for r = 1:numel(rawSrc{i})                              % merged site has several raw sensors
        R = rawSrc{i}{r};
        R = R(1:ceil(height(R)/20000):end, :);              % thin out points so it plots fast
        y = R.pm2d5;  y([false; diff(R.time) > gapBreak]) = NaN;   % break line at gaps
        plot(R.time, y, '-', 'Color', [0.85 0.1 0.1], 'LineWidth', 0.5);
    end
    C = all_data{i};
    t = datetime(C(:,1), 'ConvertFrom', 'datenum');
    y = C(:,5);  y([false; diff(t) > gapBreak]) = NaN;
    plot(t, y, '-', 'Color', [0 0.45 0.74], 'LineWidth', 1);
    hold off; grid on;
    ylim([0 1.5*prctile(C(:,5), 99.9)]);

    ttl = sprintf('%s #%d', source(i), orig_idx(i));
    if ismember(i, nMobile + mergedIdx), ttl = [ttl ' (merged)'];     end
    if i == valIdx,                      ttl = [ttl ' [VALIDATION]']; end
    title(ttl);  ylabel('PM2.5');
    if i == 1, legend('Raw', 'Cleaned'); end
end

for j = removeIdx                                           % faulty sensors that were dropped %[output:group:6f6f3844]
    nexttile; %[output:3d3acd46]
    R = raw_static{j};  R = R(1:ceil(height(R)/20000):end, :);
    y = R.pm2d5;  y([false; diff(R.time) > gapBreak]) = NaN;
    plot(R.time, y, '-', 'Color', [0.85 0.1 0.1], 'LineWidth', 0.5);
    grid on;  title(sprintf('raw static %d - REMOVED (faulty)', j));  ylabel('PM2.5');
end %[output:group:6f6f3844]
%%\ Plot one static sensor in detail
pick    = 2;          % static sensor number (as in orig_idx, e.g. static #1)
showWin = [];         % [] = whole record, or e.g. [datetime(2019,1,10) datetime(2019,1,12)]

i = find(source == "static" & orig_idx == pick);     % position in all_data / rawSrc
C = all_data{i};
t = datetime(C(:,1), 'ConvertFrom', 'datenum');

figure('Color', 'w', 'WindowState', 'maximized'); hold on; %[output:4d35db45]
for r = 1:numel(rawSrc{i})                            % merged site: several raw sensors
    R = rawSrc{i}{r};
    y = R.pm2d5;  y([false; diff(R.time) > gapBreak]) = NaN;
    plot(R.time, y, '-', 'Color', [0.85 0.1 0.1], 'LineWidth', 0.5); %[output:4d35db45]
end
y = C(:,5);  y([false; diff(t) > gapBreak]) = NaN;
plot(t, y, '-', 'Color', [0 0.45 0.74], 'LineWidth', 1.2); %[output:4d35db45]
hold off; grid on; %[output:4d35db45]

if ~isempty(showWin), xlim(showWin); end
ylim([0 1.5*prctile(C(:,5), 99.9)]); %[output:4d35db45]
title(sprintf('static #%d  -  raw vs cleaned PM2.5', pick)); %[output:4d35db45]
xlabel('Time');  ylabel('PM2.5 (\mug/m^3)'); %[output:4d35db45]
legend('Raw', 'Cleaned'); %[output:4d35db45]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%% Sliding-window model: 7 days in -> next 24 h out %%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Training targets (v5): every training static sensor AND every mobile sensor.
%   A mobile target's "truth" is its hourly PM2.5 wherever it was driving during that hour,
%   so mobile hours only count when the sensor logged >= minBlockCnt minutes in that hour.
% One SAMPLE = (target sensor, window start s0):
%   input  = the 7 days of data from all OTHER devices before s0
%   output = the target's 24 hourly-average PM2.5 values after s0 (hour h = s0+(h-1)h ... s0+h h)
% Window starts are every originStepMin minutes, so a forecast can start at any time of day.
%
% For each lead hour h = 1..24 a separate linear regression is fitted (direct multi-output):
%   PM2.5(h) = b0(h) + b1(h)*weekMean + b2(h)*(pm_latest - weekMean)
%                    + b3(h)*dailyPattern(h) + b4(h)*(lastDayMean - weekMean) + b5(h)*humidity_latest
%
%   weekMean        = neighbours' average PM2.5 over the 7 days before s0
%   latest_dev	= How far the latest 5-minute reading from nearby static and mobile sensors is above or below that weekly normal
%   dailyPattern = How the nearby sensors usually read at this clock hour, compared with their weekly normal, averaged over the past 7 days
%   lastDay_dev	= How the last 24 hours compared with the weekly norma
%   humidity_latest = last-5-min average humidity of the static neighbours
% Because b2(h) is fitted per lead, the model learns how fast the "now" signal fades
% (this replaces the hand-set tau). Every input uses only data from before s0.

historyDays   = 7;          % days of input
horizonH      = 24;         % forecast hours
originStepMin = 30;         % spacing of window starts (any time of day)
valDays       = 8;          % last valDays of the record hold the validation targets
gapDays       = 1;          % purge gap between the last training target and validation
nowWin        = 5;          % minutes averaged for the static "latest" values (and humidity)
mobWin        = 5;          % minutes averaged for the mobile "latest" value
minBlockCnt   = 20;         % min 1-min readings for an hourly target value to count
minWkCnt      = 1440;       % min neighbour minutes in the input week for a usable sample
lambda        = 0.3;        % ridge strength (0 = ordinary least squares; try 0, 0.1, 0.3, 1, 3)

%%%%%%%%%% Every device on one common 1-minute grid %%%%%%%%%%
% all_data columns: 1 time | 2 hmd | 3 tmp | 4 spd | 5 pm2d5 | 6 lat | 7 lon | 8 pm smoothed
t0 = min(cellfun(@(D) D(1,1),   all_data));
t1 = max(cellfun(@(D) D(end,1), all_data));
nT = round((t1 - t0) * 1440) + 1;
tgrid = datetime(t0, 'ConvertFrom', 'datenum') + minutes(0:nT-1)';

stDev  = find(source == "static");                    % static devices in all_data
nS     = numel(stDev);
valCol = find(stDev == valIdx);                       % validation sensor's column
trCols = setdiff(1:nS, valCol);                       % training static columns

S = nan(nT, nS);  H = nan(nT, nS);                    % static PM2.5 and humidity, one column each
for c = 1:nS
    D = all_data{stDev(c)};
    k = round((D(:,1) - t0) * 1440) + 1;
    S(k, c) = D(:,5);  H(k, c) = D(:,2);
end

mobDev = trainIdx(source(trainIdx) == "mobile");     % mobile devices in all_data
nM     = numel(mobDev);
M = nan(nT, nM);                                      % mobile PM2.5, one column each
for c = 1:nM
    D = all_data{mobDev(c)};
    k = round((D(:,1) - t0) * 1440) + 1;
    M(k, c) = D(:,5);
end

% All devices side by side: columns 1..nS = static, nS+1..nS+nM = mobile
A     = [S M];
mCols = nS + (1:nM);                                  % mobile columns of A
isMob = [false(1, nS) true(1, nM)];
tgCols = [trCols mCols];                              % TRAINING TARGETS: static + mobile
fprintf('Training targets: %d static + %d mobile\n', numel(trCols), nM); %[output:703341f3]
% --- "latest" values = trailing averages (only look backward) ---
Snow = movmean(S, [nowWin-1 0], 1, 'omitnan');
Hnow = movmean(mean(H(:, trCols), 2, 'omitnan'), [nowWin-1 0], 'omitnan');

%%%%%%%%%% Time split of the window starts %%%%%%%%%%
histMin    = historyDays * 1440;
horizonMin = horizonH * 60;
valStart   = nT - valDays*1440 + 1;                   % first grid row of the validation period
trainEnd   = valStart - gapDays*1440 - 1;             % last grid row a training target may touch

allStarts   = (histMin+1 : originStepMin : nT-horizonMin+1)';     % every possible window start
trainStarts = allStarts(allStarts + horizonMin - 1 <= trainEnd);  % target fully before the gap
valStarts   = allStarts(allStarts >= valStart);                   % target fully in validation
if isempty(trainStarts) || isempty(valStarts)
    error('Record too short for %d-day history + %d-day gap + %d-day validation.', historyDays, gapDays, valDays);
end

fprintf('\n---- TIME SPLIT ----\n'); %[output:281bb2a7]
fprintf('  input-only history : %s  to  %s\n', tgrid(1), tgrid(histMin)); %[output:7422c593]
fprintf('  training targets   : %s  to  %s  (%d window starts)\n', tgrid(trainStarts(1)), tgrid(trainEnd), numel(trainStarts)); %[output:116da820]
fprintf('  purge gap          : %d day(s)\n', gapDays); %[output:0f2790dd]
fprintf('  validation targets : %s  to  %s  (%d window starts)\n', tgrid(valStart), tgrid(end), numel(valStarts)); %[output:6dadb6f5]
%%%%%%%%%% Neighbour series for each possible target %%%%%%%%%%
% Neighbours of target j = every OTHER training device:
%   static neighbours = training static sensors except j (all of them if j is mobile/validation)
%   mobile neighbours = mobile sensors except j            (all of them if j is static/validation)
% weekMean / lastDay / dailyPattern use the static neighbours (continuous records);
% pm_latest averages the static and mobile neighbours' latest values.
F = cell(nS + nM, 1);
for j = [tgCols valCol]
    stNb = setdiff(trCols, j);                        % static neighbour columns of S
    mbNb = setdiff(mCols, j) - nS;                    % mobile neighbour columns of M
    nbCols = stNb;
    nb = mean(S(:, nbCols), 2, 'omitnan');
    f.wk    = movmean(nb, [histMin-1 0], 'omitnan');            % trailing 7-day mean
    f.wkCnt = movsum(double(~isnan(nb)), [histMin-1 0]);        % how many minutes it used
    f.dy    = movmean(nb, [1439 0], 'omitnan');                 % trailing 24-h mean
    f.blk   = movmean(nb, [0 59], 'omitnan');                   % 60-min block starting at each minute
    f.pS    = mean(Snow(:, nbCols), 2, 'omitnan');              % static neighbours' latest
    f.pM    = movmean(mean(M(:, mbNb), 2, 'omitnan'), [mobWin-1 0], 'omitnan');   % mobile neighbours' latest
    y       = A(:, j);
    f.yb    = movmean(y, [0 59], 'omitnan');                    % target's hourly blocks (truth)
    f.yb(movsum(double(~isnan(y)), [0 59]) < minBlockCnt) = NaN;
    if isMob(j), w = mobWin; else, w = nowWin; end
    f.last  = fillmissing(movmean(y, [w-1 0], 'omitnan'), 'previous');   % target's own last value (baseline)
    f.own   = movmean(y, [histMin-1 0], 'omitnan');             % target's own week mean (baseline)
    F{j} = f;
end

%%%%%%%%%% Build the sliding-window samples %%%%%%%%%%
off  = (0:horizonH-1) * 60;                           % start of each forecast hour after s0
dOff = reshape(1:historyDays, 1, 1, []) * 1440;       % same clock time on each of the past 7 days

sets = struct('name',   {'train', 'val_seen', 'val'}, ...
              'starts', {trainStarts, valStarts, valStarts}, ...
              'cols',   {tgCols, trCols, valCol});
% train    = training sensors (static + mobile), training period   -> fit
% val_seen = training STATIC sensors, validation period          -> new time, known places (static only)
% val      = validation sensor, validation period        -> new time AND new place (main score)

for k = 1:numel(sets) %[output:group:143d949c]
    st = sets(k).starts;  b = st - 1;                 % b = last minute of the input week
    [Wk, WkC, Dev, Dy, Hum, PL, Pf, Y, Pers, Hm, Col] = deal([]);
    for j = sets(k).cols
        f  = F{j};
        wk = f.wk(b);
        pl = mean([f.pS(b) f.pM(b)], 2, 'omitnan');
        dv = pl - wk;          dv(isnan(dv)) = 0;     % no recent data -> no correction
        dy = f.dy(b) - wk;     dy(isnan(dy)) = 0;
        pf = mean(f.blk(st + off - dOff), 3, 'omitnan') - wk;  pf(isnan(pf)) = 0;

        Wk = [Wk; wk];  WkC = [WkC; f.wkCnt(b)];  Dev = [Dev; dv];  Dy = [Dy; dy];   %#ok<AGROW>
        Hum = [Hum; Hnow(b)];  PL = [PL; pl];  Pf = [Pf; pf];  Y = [Y; f.yb(st + off)];   %#ok<AGROW>
        Pers = [Pers; f.last(b)];  Hm = [Hm; f.own(b)];  Col = [Col; repmat(j, numel(st), 1)];   %#ok<AGROW>
    end
    sets(k).Wk = Wk;  sets(k).WkC = WkC;  sets(k).Dev = Dev;  sets(k).Dy = Dy;
    sets(k).Hum = Hum;  sets(k).PL = PL;  sets(k).Pf = Pf;  sets(k).Y = Y;
    sets(k).Pers = Pers;  sets(k).Hm = Hm;  sets(k).Col = Col;
    fprintf('  %-9s %6d samples (%d sensors x %d starts)\n', sets(k).name, numel(Wk), numel(sets(k).cols), numel(st)); %[output:5ffe85df]
end %[output:group:143d949c]
%%%%%%%%%% Fit: one RIDGE regression per lead hour %%%%%%%%%%
% Ridge = least squares + a penalty lambda*sum(b.^2) that pulls the slopes toward 0.
% Features are standardised first so the penalty treats them equally; the intercept is
% not penalised. Coefficients are converted back to original units, so beta is used
% exactly as before when predicting.
Tr      = sets(1);
humFill = mean(Tr.Hum, 'omitnan');                    % fill missing humidity with the training mean
nFeat   = 5;
beta    = nan(nFeat+1, horizonH);
nFit    = zeros(1, horizonH);
for h = 1:horizonH
    Xh = [Tr.Wk Tr.Dev Tr.Pf(:,h) Tr.Dy Tr.Hum];
    Xh(isnan(Xh(:,5)), 5) = humFill;
    use = all(isfinite(Xh), 2) & isfinite(Tr.Y(:,h)) & Tr.WkC >= minWkCnt;
    nFit(h) = nnz(use);
    Xu = Xh(use,:);  yu = Tr.Y(use,h);
    mu = mean(Xu, 1);  sd = std(Xu, 0, 1);  sd(sd == 0) = 1;
    Z  = (Xu - mu) ./ sd;                             % standardised features
    b  = (Z'*Z + lambda*nFit(h)*eye(nFeat)) \ (Z'*(yu - mean(yu)));   % ridge slopes
    beta(2:end,h) = b ./ sd';                         % back to original units
    beta(1,h)     = mean(yu) - mu*beta(2:end,h);      % unpenalised intercept
end

%%%%%%%%%% Predict every set %%%%%%%%%%
for k = 1:numel(sets)
    P = nan(size(sets(k).Y));
    for h = 1:horizonH
        Xh = [sets(k).Wk sets(k).Dev sets(k).Pf(:,h) sets(k).Dy sets(k).Hum];
        Xh(isnan(Xh(:,5)), 5) = humFill;
        P(:,h) = [ones(size(Xh,1),1) Xh] * beta(:,h);
    end
    sets(k).P = max(P, 0);                            % PM2.5 can't be negative
end

%%%%%%%%%% Fitted model %%%%%%%%%%
coefNames = {'intercept','weekMean','latest_dev','dailyPattern','lastDay_dev','humidity_latest'};
showH = [1 3 6 12 24];
fprintf('\n---- FITTED MODEL (ridge, lambda = %g, %d-%d training samples per lead) ----\n', lambda, min(nFit), max(nFit)); %[output:5f37e1d7]
disp(array2table(beta(:, showH), 'RowNames', coefNames, ... %[output:group:4cd22a81] %[output:386d3f38]
    'VariableNames', arrayfun(@(h) sprintf('lead_%dh', h), showH, 'UniformOutput', false))); %[output:group:4cd22a81] %[output:386d3f38]

%%%%%%%%%% How Good Is It? %%%%%%%%%%
% Main score: the held-out sensor in the held-out week (new place + new time).
V       = sets(3);
test_name = valName;
actual  = V.Y(:);
pred    = V.P(:);
pers    = repmat(V.Pers, horizonH, 1);                % own last 5-min value, held for all 24 h
hmean   = repmat(V.Hm,   horizonH, 1);                % own past-week average
val   = isfinite(actual) & isfinite(pred) & isfinite(pers) & isfinite(hmean);   % same hours for every method
rmse  = @(p) sqrt(mean((p(val) - actual(val)).^2));
nrmse = @(p) rmse(p) / sqrt(mean(actual(val).^2));       % RMSE / RMS of the ground truth
mae   = @(p) mean(abs(p(val) - actual(val)));
r2    = @(p) 1 - sum((p(val) - actual(val)).^2) / sum((actual(val) - mean(actual(val))).^2);

results = table( ...
    [nrmse(pred); nrmse(pers); nrmse(hmean)], ...
    [mae(pred);   mae(pers);   mae(hmean)], ...
    [r2(pred);    r2(pers);    r2(hmean)], ...
    'VariableNames', {'NRMSE', 'MAE_ugm3', 'R2'}, ...
    'RowNames',      {'Regression', 'Baseline: last value', 'Baseline: week average'});

fprintf('\n---- 24-h FORECAST RESULTS for %s (%d windows, %d hourly values) ----\n', test_name, numel(valStarts), nnz(val)); %[output:75350edc]
disp(results); %[output:0930143f]
% Generalisation check: train vs new time vs new time + new place.
% A big jump from row 1 to rows 2-3 means the model is overfitting the training weeks.
nrmseOf = @(p, a) sqrt(mean((p(isfinite(p) & isfinite(a)) - a(isfinite(p) & isfinite(a))).^2)) ...
                / sqrt(mean(a(isfinite(p) & isfinite(a)).^2));
gen = nan(3, 3);
for k = 1:3
    a = sets(k).Y(:);
    gen(k,:) = [nrmseOf(sets(k).P(:), a), ...
                nrmseOf(repmat(sets(k).Pers, horizonH, 1), a), ...
                nrmseOf(repmat(sets(k).Hm,   horizonH, 1), a)];
end
gen_table = array2table(gen, 'VariableNames', {'Regression', 'LastValue', 'WeekAverage'}, ...
    'RowNames', {'train sensors, train period (in-sample)', ...
                 'train static sensors, validation period', ...
                 'validation sensor, validation period'});
fprintf('---- NRMSE: does it generalise? ----\n'); %[output:8f451c98]
disp(gen_table); %[output:4c75ab46]

% In-sample fit split by target type (static vs mobile)
typ = nan(2, 3);  typNames = {};
for k = 1                                              % training period only (validation is static-only) %[output:group:59dc9b94]
    for mob = [false true]
        r  = isMob(sets(k).Col) == mob;
        a  = sets(k).Y(r,:);  a = a(:);
        typ(numel(typNames)+1, :) = [nrmseOf(reshape(sets(k).P(r,:), [], 1), a), ...
            nrmseOf(repmat(sets(k).Pers(r), horizonH, 1), a), ...
            nrmseOf(repmat(sets(k).Hm(r),   horizonH, 1), a)];
        if mob, nm = 'mobile'; else, nm = 'static'; end
        typNames{end+1} = sprintf('%s targets, %s', nm, sets(k).name);   %#ok<SAGROW>
        fprintf('  %-26s %5d usable hourly values\n', typNames{end}, nnz(isfinite(a))); %[output:2e50381d]
    end
end %[output:group:59dc9b94]
disp(array2table(typ, 'VariableNames', {'Regression', 'LastValue', 'WeekAverage'}, 'RowNames', typNames)); %[output:357870b0]

% Error by lead hour (does the forecast get worse further ahead?)
nrmseLead = nan(horizonH, 3);
for h = 1:horizonH
    a = V.Y(:,h);
    nrmseLead(h,:) = [nrmseOf(V.P(:,h), a), nrmseOf(V.Pers, a), nrmseOf(V.Hm, a)];
end

%%%%%%%%%% Pearson r Table %%%%%%%%%%
% Pearson r = how strongly two things rise and fall together.
%   +1 = move together perfectly, 0 = no link, -1 = move in opposite directions.
% Here: the validation sensor's actual hourly PM2.5 vs each model input and each forecast.

Xin  = [repmat(V.PL, horizonH, 1), V.Pf(:), repmat(V.Hum, horizonH, 1)];   % pm_latest, dailyPattern, humidity
ok_r   = val & all(~isnan(Xin), 2);                   % hours where everything is available
r_all  = corrcoef([actual(ok_r) Xin(ok_r,:) pred(ok_r) pers(ok_r) hmean(ok_r)]);
r_vals = round(r_all(2:end, 1), 2);                   % r between actual PM2.5 and each column

input_names = {'pm_latest (static + mobile)'; 'dailyPattern (neighbours, same time of day)'; ...
    'humidity_latest'; 'regression forecast'; 'last value'; 'week average'};
pearson_table = table(r_vals, 'RowNames', input_names, ... %[output:group:693db32d] %[output:99ec3783]
    'VariableNames', {'actual_PM25_r'}) %[output:group:693db32d] %[output:99ec3783]

%%%%%%%%%% Plain-Words Summary %%%%%%%%%%
bias = mean(pred(val) - actual(val));                 % + = guesses too high, - = too low
if bias >= 0, dir = 'high'; else, dir = 'low'; end
bestBase = min(nrmse(pers), nrmse(hmean));            % stronger of the two baselines
if nrmse(pred) < bestBase, cmp = 'better'; else, cmp = 'worse'; end

s = sprintf(['For %s, over the held-out final %d days, the 24-hour forecast''s typical error was %.1f ug/m3 ' ...
    '(NRMSE = %.2f, about %.0f%% of the typical PM2.5 level) and it explained %.0f%% of the variation ' ...
    '(R^2 = %.2f). On average it guessed %.1f ug/m3 too %s, and it did %s than the best simple baseline ' ...
    '(last value or week average, NRMSE = %.2f).'], ...
    test_name, valDays, mae(pred), nrmse(pred), 100*nrmse(pred), 100*r2(pred), r2(pred), ...
    abs(bias), dir, cmp, bestBase);

lines = textwrap({s}, 80);
fprintf('\n%s\n', lines{:}); %[output:3e8615fd]
% Baselines to beat:
% "Last value": static #2's last 5-minute reading, held flat.
% "Week average": static #2's past-week average.

%%%%%%%%%% Plot Model vs Actual %%%%%%%%%%
nH = floor(nT / 60);                                  % number of full hours on the grid
hr = @(v) mean(reshape(v(1:60*nH), 60, []), 1, 'omitnan')';
tH = tgrid(1:60:60*nH);

% back-to-back (non-overlapping) validation windows, one per day
chain = find(mod(valStarts - valStarts(1), 1440) == 0);
tC = tgrid(valStarts(chain) + off)';  tC = tC(:) + minutes(30);   % centre of each forecast hour
pC = V.P(chain,:)';                    pC = pC(:);
bC = repmat(V.Pers(chain)', horizonH, 1);   bC = bC(:);
mC = repmat(V.Hm(chain)',   horizonH, 1);   mC = mC(:);

figure('Name','3 - Forecast vs actual','Color','w'); %[output:2674af45]

subplot(3,1,1); hold on;                              % whole record, hourly %[output:2674af45]
plot(tH, hr(S(:,valCol)), 'k', 'LineWidth', 1); %[output:2674af45]
plot(tC, pC, 'r', 'LineWidth', 1.5); %[output:2674af45]
plot(tC, bC, 'Color', [0.2 0.5 0.9]); %[output:2674af45]
plot(tC, mC, 'Color', [0.5 0.5 0.5], 'LineStyle', '--'); %[output:2674af45]
xline(tgrid(histMin), 'k:', 'end of input-only week'); %[output:2674af45]
xline(tgrid(trainEnd), 'm--', 'end of training targets'); %[output:2674af45]
xline(tgrid(valStart), 'g--', 'validation starts'); %[output:2674af45]
legend('actual','24-h forecast','last value','week average', 'Location', 'best'); grid on; %[output:2674af45]
ylabel('PM2.5 (\mug/m^3)'); title([test_name ' - hourly averages (forecasts = one per validation day)']); %[output:2674af45]

subplot(3,1,2); hold on;                              % one window: the day before + the forecast day %[output:2674af45]
m  = chain(ceil(numel(chain)/2));                     % a forecast in the middle of the validation period
s0 = valStarts(m);
z  = max(1, s0-1440) : s0+horizonMin-1;
tStep = [tgrid(s0 + off); tgrid(s0 + horizonMin - 1)];
plot(tgrid(z), S(z,valCol), 'k', 'LineWidth', 1); %[output:2674af45]
stairs(tStep, [V.P(m,:)'; V.P(m,end)], 'r', 'LineWidth', 1.5); %[output:2674af45]
stairs(tStep, [V.Y(m,:)'; V.Y(m,end)], 'Color', [0.3 0.3 0.3], 'LineStyle', ':', 'LineWidth', 1.2); %[output:2674af45]
yline(V.Pers(m), 'Color', [0.2 0.5 0.9]); %[output:2674af45]
xline(tgrid(s0), 'g--', 'forecast start'); %[output:2674af45]
legend('actual (1-min)','24-h forecast (hourly)','actual (hourly)','last value', 'Location', 'best'); grid on; %[output:2674af45]
ylabel('PM2.5 (\mug/m^3)'); title('Example window'); %[output:2674af45]

subplot(3,1,3); hold on;                              % error vs how far ahead %[output:2674af45]
plot(1:horizonH, nrmseLead(:,1), 'r-o', 'LineWidth', 1.5); %[output:2674af45]
plot(1:horizonH, nrmseLead(:,2), '-o', 'Color', [0.2 0.5 0.9]); %[output:2674af45]
plot(1:horizonH, nrmseLead(:,3), '--o', 'Color', [0.5 0.5 0.5]); %[output:2674af45]
legend('regression','last value','week average', 'Location', 'best'); grid on; %[output:2674af45]
xlabel('hours ahead'); ylabel('NRMSE'); xlim([1 horizonH]); %[output:2674af45]
title(sprintf('%s - error by lead hour (all %d validation windows)', test_name, numel(valStarts))); %[output:2674af45]
% end

